css:
@page {
    size: A4;
    margin: 5mm;
}

.bg-infos {
    background-color: #0dcaf0;
}

.borders { border: 1px solid #000; }
.borders-top { border-top: 1px solid #000; }
.borders-bottom { border-bottom: 1px solid #000; }
.borders-start { border-left: 1px solid #000; }
.borders-end { border-right: 1px solid #000; }
.borders-2 { border-width: 2px; }

.rounded-2 { border-radius: 8px; }    /* Medium */

/* ===== Row ===== */
.rows {
    display: flex;          /* Align columns side by side */
    flex-wrap: wrap;        /* Wrap to next line if needed */
}

/* ===== Columns ===== */


.cols-1  { width: 8.3333%; }
.cols-2  { width: 16.6667%; }
.cols-3  { width: 25%; }
.cols-4  { width: 33.3333%; } 
.cols-5  { width: 41.6667%; }
.cols-6  { width: 50%; }
.cols-7  { width: 58.3333%; }
.cols-8  { width: 66.6667%; }
.cols-9  { width: 75%; }
.cols-10 { width: 83.3333%; }
.cols-11 { width: 91.6667%; }
.cols-12 { width: 100%; }
.cols-13 { width: 15.3333%; }
.cols-77 { width: 51.3333%; }

/* Normal and bold font weights */
.fweight-1 { font-weight: bold; }       /* 700 */
.fweight-2 { font-weight: bolder; }     /* bolder relative to parent */

/* Font sizes */
.fsize-0 { font-size: 9px; }
.fsize-1 { font-size: 10px; }
.fsize-2 { font-size: 12px; }
.fsize-3 { font-size: 24px; }

/* ===== Right padding (end) ===== */
.pae-0 { padding-right: 0; }
.pae-1 { padding-right: 2px; }
.pae-2 { padding-right: 4px; }
.pae-3 { padding-right: 7px; }

.pas-4 { padding-left: 12px; }

.pax-1 { padding-left: 4px; padding-right: 4px; }
.pax-2 { padding-left: 8px; padding-right: 8px; }
.pax-3 { padding-left: 16px; padding-right: 16px; }
.pax-4 { padding-left: 24px; padding-right: 24px; }
.pax-5 { padding-left: 48px; padding-right: 48px; }

.pay-1 { padding-top: 4px; padding-bottom: 4px; }
.pay-2 { padding-top: 8px; padding-bottom: 8px; }
.pay-3 { padding-top: 16px; padding-bottom: 16px; }
.pay-4 { padding-top: 24px; padding-bottom: 24px; }
.pay-5 { padding-top: 48px; padding-bottom: 48px; }

.may-1 { margin-top: 4px; margin-bottom: 4px; }

.mx-autos {
    margin-left: auto;
    margin-right: auto;
}

.d-flexs { display: flex; }

.flex-center {
    display: flex;
    align-items: center;
    justify-content: center;
} 

.texts-start { text-align: left; }
.texts-end { text-align: right; }

.fixed-top {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 1030;
}

/*----------------- Table styling for the main data --------------------*/

/* Header styling */
.header-details {
    display: flex;
    justify-content: space-between;
    /*margin-bottom: 10px;*/
}

.recipient-details { width: 60%; }

.challan-details { width: 35%; }

/* Main Table styling */
.ss th { font-weight: bold; color: #000; }

.delivery-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed; 
}

.delivery-table th, .delivery-table td {
    border: 1px solid #000;
    padding: 5px;
    text-align: left;
    vertical-align: top;
    height: 25px; /* Ensures consistent row height */
}

/* Column specific alignment/widths */
.delivery-table th:nth-child(1), .delivery-table td:nth-child(1) { width: 5%; text-align: center; } /* SN */
.delivery-table th:nth-child(2), .delivery-table td:nth-child(2) { width: 30%; } /* Description */
.delivery-table th:nth-child(3), .delivery-table td:nth-child(3) { width: 13%; text-align: center; } /* Quantity */
.delivery-table th:nth-child(4), .delivery-table td:nth-child(4) { width: 25%; } /* Process */
.delivery-table th:nth-child(5), .delivery-table td:nth-child(5) { width: 10%; text-align: right; } /* HSN */
.delivery-table th:nth-child(6), .delivery-table td:nth-child(6) { width: 8%; text-align: right; } /* Rate */
.delivery-table th:nth-child(7), .delivery-table td:nth-child(7) { width: 9%; text-align: right; } /* Value */


.footer-row .total-label {
    text-align: right;
    font-weight: bold;
}
